// Parse hours input
const input = items[0].json.message.text;
const lines = input.split('\n').map(l => l.trim()).filter(l => l);

if (lines.length < 2) {
  return [{
    json: {
      error: true,
      message: "❌ Please provide hours and description"
    }
  }];
}

const hours = parseFloat(lines[0]);
const description = lines[1];
let workDate = lines[2] || 'today';

// Parse date
if (workDate.toLowerCase() === 'today') {
  workDate = new Date().toISOString().split('T')[0];
} else if (workDate.toLowerCase() === 'yesterday') {
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  workDate = yesterday.toISOString().split('T')[0];
}

// BMF hourly rate (configure this)
const hourlyRate = 35; // £35/hour
const earnings = hours * hourlyRate;

return [{
  json: {
    error: false,
    hours_worked: hours,
    task_description: description,
    work_date: workDate,
    hourly_rate: hourlyRate,
    earnings: earnings,
    status: 'logged'
  }
}];

