parameters.functionCode:
// Format weekly hours
const entries = items;

if (entries.length === 0) {
  return [{
    json: {
      message: "📭 No hours logged this week"
    }
  }];
}

let message = "📊 **This Week's Hours - BMF**\n\n";
let totalHours = 0;
let totalEarnings = 0;

for (const entry of entries) {
  const date = new Date(entry.json.work_date).toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
  const hours = parseFloat(entry.json.hours_worked || 0);
  const earnings = parseFloat(entry.json.earnings || 0);

  message += `**${date}**\n`;
  message += `⏱️ ${hours} hours\n`;
  message += `📝 ${entry.json.task_description}\n`;
  message += `💰 £${earnings.toFixed(2)}\n`;
  message += `\n`;

  totalHours += hours;
  totalEarnings += earnings;
}

message += `**WEEK TOTAL**\n`;
message += `⏱️ ${totalHours} hours\n`;
message += `💵 £${totalEarnings.toFixed(2)}`;

return [{
  json: {
    message: message,
    total_hours: totalHours,
    total_earnings: totalEarnings
  }
}];

// Format monthly hours with weekly breakdown
const entries = items;

if (entries.length === 0) {
  return [{
    json: {
      message: "📭 No hours logged this month"
    }
  }];
}

let message = "📊 **This Month's Hours - BMF**\n\n";
let totalHours = 0;
let totalEarnings = 0;

// Group by week
const weeks = {};

for (const entry of entries) {
  const date = new Date(entry.json.work_date);
  const weekStart = new Date(date);
  weekStart.setDate(date.getDate() - date.getDay());
  const weekKey = weekStart.toISOString().split('T')[0];

  if (!weeks[weekKey]) {
    weeks[weekKey] = {
      hours: 0,
      earnings: 0,
      entries: []
    };
  }

  const hours = parseFloat(entry.json.hours_worked || 0);
  const earnings = parseFloat(entry.json.earnings || 0);

  weeks[weekKey].hours += hours;
  weeks[weekKey].earnings += earnings;
  weeks[weekKey].entries.push(entry.json);

  totalHours += hours;
  totalEarnings += earnings;
}

// Format output
const weekKeys = Object.keys(weeks).sort().reverse();

for (const weekKey of weekKeys) {
  const weekData = weeks[weekKey];
  const weekDate = new Date(weekKey).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });

  message += `**Week of ${weekDate}**\n`;
  message += `⏱️ ${weekData.hours} hours | 💰 £${weekData.earnings.toFixed(2)}\n`;
  message += `\n`;
}

message += `\n**MONTH TOTAL**\n`;
message += `⏱️ ${totalHours} hours\n`;
message += `💵 £${totalEarnings.toFixed(2)}\n`;
message += `📊 Avg per week: £${(totalEarnings / weekKeys.length).toFixed(2)}`;

return [{
  json: {
    message: message,
    total_hours: totalHours,
    total_earnings: totalEarnings,
    weeks_worked: weekKeys.length
  }
}];

// Parse timesheet period
const input = items[0].json.message.text;
const lines = input.split('\n').map(l => l.trim()).filter(l => l);

if (lines.length < 2) {
  return [{
    json: {
      error: true,
      message: "❌ Please provide start and end dates"
    }
  }];
}

return [{
  json: {
    error: false,
    start_date: lines[0],
    end_date: lines[1]
  }
}];

